<?php use Addons\Grh\GrhService as S; require __DIR__ . '/_h.php'; $man = can('grh.manage'); $d = $editDep ?? []; $po = $editPoste ?? [];
$render = function (array $nodes) use (&$render): string { $h = ''; foreach ($nodes as $n) { $h .= '<li><div class="grh-node"><div class="d-flex justify-content-between gap-2"><b>' . e($n['name']) . '</b><span class="badge text-bg-secondary">' . (int) $n['n'] . '</span></div><div class="who">'
    . ($n['manager'] ? '<i class="bi bi-person-badge"></i> ' . e($n['manager']) . ($n['manager_poste'] ? ' — ' . e($n['manager_poste']) : '') : e(t('Responsable non désigné'))) . '</div>'
    . ($n['staff'] ? '<details class="small mt-1"><summary>' . e(t('Voir l\'équipe')) . '</summary>' . implode('', array_map(fn ($s) => '<div><a href="' . e(url('/grh/employes/' . $s['id'])) . '">' . e($s['first_name'] . ' ' . $s['last_name']) . '</a> <span class="text-secondary">' . e($s['poste']) . '</span></div>', $n['staff'])) . '</details>' : '')
    . (can('grh.manage') ? '<a class="small" href="' . e(url('/grh/structure', ['departement' => $n['id']])) . '">' . e(t('Modifier')) . '</a>' : '') . '</div>' . ($n['children'] ? '<ul>' . $render($n['children']) . '</ul>' : '') . '</li>'; } return $h; }; ?>
<link rel="stylesheet" href="<?= e(asset('addons/grh/grh.css')) ?>">
<div class="row g-3"><div class="col-lg-7"><div class="card"><div class="card-header"><i class="bi bi-diagram-3"></i> <?= e(t('Organigramme')) ?> — <?= e(setting('company_name')) ?></div><div class="card-body">
  <?php if ($tree): ?><ul class="grh-org"><?= $render($tree) ?></ul><?php else: ?><p class="text-secondary mb-0"><?= e(t('Créez vos départements (Direction générale, Finances, Opérations…) pour dessiner l\'organigramme.')) ?></p><?php endif; ?></div></div></div>
<div class="col-lg-5">
  <?php if ($man): ?><div class="card mb-3"><div class="card-header"><?= e(t($d ? 'Modifier le département' : 'Nouveau département')) ?></div><div class="card-body"><form method="post" action="<?= e(url('/grh/structure/departements')) ?>" class="row g-2"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) ($d['id'] ?? 0) ?>">
    <?= grh_field('name', 'Nom', $d['name'] ?? '', 'text', 'required maxlength="120"', 'col-12') ?><?= grh_select('parent_id', 'Dépend de', grh_opts(array_filter($deps, fn ($x) => (int) $x['id'] !== (int) ($d['id'] ?? 0)), 'name', '— (sommet)'), $d['parent_id'] ?? '', '', 'col-6', false) ?>
    <?= grh_select('manager_id', 'Responsable', grh_opts($actifs, fn ($r) => $r['last_name'] . ' ' . $r['first_name']), $d['manager_id'] ?? '', '', 'col-6', false) ?><div class="col-12"><button class="btn btn-sm btn-primary"><?= e(t('Enregistrer')) ?></button><?php if ($d): ?> <a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/grh/structure')) ?>"><?= e(t('Annuler')) ?></a><?php endif; ?></div></form></div></div>
  <div class="card mb-3"><div class="card-header"><?= e(t($po ? 'Modifier le poste' : 'Nouveau poste')) ?></div><div class="card-body"><form method="post" action="<?= e(url('/grh/structure/postes')) ?>" class="row g-2"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int) ($po['id'] ?? 0) ?>">
    <?= grh_field('title', 'Intitulé du poste', $po['title'] ?? '', 'text', 'required maxlength="120"', 'col-12') ?><?= grh_select('departement_id', 'Département', grh_opts($deps, 'name'), $po['departement_id'] ?? '', '', 'col-5', false) ?><?= grh_field('grade', 'Catégorie / grade', $po['grade'] ?? '', 'text', 'maxlength="40"', 'col-3') ?>
    <?= grh_field('base_salary', 'Salaire de référence', $po['base_salary'] ?? '', 'text', 'inputmode="decimal"', 'col-4') ?><div class="col-12"><button class="btn btn-sm btn-primary"><?= e(t('Enregistrer')) ?></button><?php if ($po): ?> <a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/grh/structure')) ?>"><?= e(t('Annuler')) ?></a><?php endif; ?></div></form></div></div><?php endif; ?>
  <div class="card"><div class="card-header"><i class="bi bi-briefcase"></i> <?= e(t('Postes')) ?></div><table class="table table-sm mb-0 small align-middle"><thead><tr><th><?= e(t('Poste')) ?></th><th><?= e(t('Département')) ?></th><th class="num"><?= e(t('Effectif')) ?></th><?php if (can('grh.paie')): ?><th class="num"><?= e(t('Référence')) ?></th><?php endif; ?><th></th></tr></thead><tbody>
    <?php foreach ($allPostes as $x): ?><tr><td><?= e($x['title']) ?><?= $x['grade'] ? ' <span class="text-secondary">(' . e($x['grade']) . ')</span>' : '' ?></td><td><?= e($x['departement']) ?></td><td class="num"><?= (int) $x['n'] ?></td><?php if (can('grh.paie')): ?><td class="num"><?= money($x['base_salary']) ?></td><?php endif; ?>
      <td class="text-end"><?php if ($man): ?><a class="btn btn-sm btn-outline-secondary" href="<?= e(url('/grh/structure', ['poste' => $x['id']])) ?>"><i class="bi bi-pencil"></i></a><?php endif; ?></td></tr><?php endforeach; ?>
    <?php if (!$allPostes): ?><tr><td colspan="5" class="text-center text-secondary py-3"><?= e(t('Aucun poste.')) ?></td></tr><?php endif; ?></tbody></table></div>
</div></div>
